static const char mira_beta_params_html[] =
    "\n"
    "<!DOCTYPE html>\n"
    "<html lang=\"fr\">\n"
    "<head>\n"
    "<meta charset=\"UTF-8\">\n"
    "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n"
    "<title>%APP% - Paramètres</title>\n"
    "<style>\n"
    ":root{--bg:%LIGHTCOLOR%;--panel:%DARKCOLOR%;--active:%ACTIVECOLOR%;--txt:%TEXTCOLOR%;--ink:#263238;--muted:#607d8b;--line:#d9e2e6;--soft:#f5f8f9;--danger:#9b4a4a;}\n"
    "*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Arial,sans-serif;color:var(--ink)}\n"
    "header{background:var(--panel);color:var(--txt);position:sticky;top:0;z-index:5;box-shadow:0 2px 12px rgba(0,0,0,.12)}\n"
    ".bar{max-width:1040px;margin:auto;min-height:66px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{font-size:22px;font-weight:800;white-space:nowrap}.nav{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.nav a{color:var(--txt);text-decoration:none;font-weight:700;padding:10px 12px;border-radius:12px}.nav a:hover,.nav a.active{background:rgba(255,255,255,.14)}\n"
    "main{max-width:940px;margin:28px auto;padding:0 18px 42px}.hero{margin-bottom:16px}.hero h1{font-size:36px;margin:0 0 7px}.hero p{margin:0;color:#455a64;line-height:1.45}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#fff;border-radius:20px;padding:24px;box-shadow:0 5px 20px rgba(0,0,0,.10)}.card.full{grid-column:1/-1}.card h2{margin:0 0 6px;font-size:22px}.hint{font-size:14px;color:var(--muted);line-height:1.45;margin:0 0 18px}.field{margin:0 0 16px}.field:last-child{margin-bottom:0}label,.field-label{display:block;font-weight:700;margin:0 0 7px}input[type=text],input[type=password],input[type=number],input[type=time],select,.box,.box1{display:block;width:100%% !important;min-height:46px;padding:11px 14px;border:1.8px solid #78909c;border-radius:12px;font-size:16px;background:#fff;color:var(--ink);text-align:left !important}input:focus,select:focus{outline:none;border-color:var(--active);box-shadow:0 0 0 3px rgba(0,0,0,.05)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.btn,.Bouton{border:0;border-radius:14px;padding:12px 18px;background:var(--active);color:#fff;font-weight:800;font-size:16px;cursor:pointer;text-decoration:none;width:auto}.btn.secondary{background:#607d8b}.btn.danger{background:var(--danger)}.btn:active,.Bouton:active{transform:scale(.98)}.quick{display:grid;gap:10px}.quick a{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px 15px;border:1px solid var(--line);border-radius:14px;background:var(--soft);color:var(--ink);font-weight:700;text-decoration:none}.quick a span{color:var(--muted);font-weight:400;font-size:13px}.switchline{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 16px;background:var(--soft);border-radius:14px;margin:10px 0}.switchline input[type=checkbox]{width:26px;height:26px;accent-color:var(--active)}.hide{display:none!important}.section-title{font-size:17px;font-weight:800;margin:22px 0 12px;padding-top:18px;border-top:1px solid var(--line)}.empty{padding:16px;border:1px dashed #b0bec5;border-radius:14px;color:var(--muted);background:var(--soft)}.network-list{display:grid;gap:10px}.network-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line);border-radius:14px;background:var(--soft)}.network-id{display:inline-flex;align-items:center;justify-content:center;min-width:36px;height:36px;border-radius:10px;background:#e5ecef;color:#546e7a;font-weight:800}.network-button{flex:1;border:0;background:transparent;color:var(--ink);text-align:left;font-size:16px;font-weight:800;cursor:pointer;padding:8px}.dangerbox{border-left:4px solid var(--danger);padding-left:16px}.status{padding:16px;border-radius:14px;background:var(--soft);border:1px solid var(--line);font-weight:700}.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere}.footnote{margin-top:18px;color:var(--muted);font-size:13px;line-height:1.45}.display-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.display-grid .field{margin:0}.unit-wrap{position:relative}.unit-wrap input{padding-right:50px}.unit{position:absolute;right:15px;top:14px;color:var(--muted);font-weight:700;pointer-events:none}\n"
    "@media(max-width:700px){.bar{align-items:flex-start;flex-direction:column;padding-top:14px;padding-bottom:12px}.nav{justify-content:flex-start}.grid,.display-grid{grid-template-columns:1fr}.card.full{grid-column:auto}.hero h1{font-size:30px}}\n"
    "</style>\n"
    "</head>\n"
    "<body>\n"
    "<header><div class=\"bar\"><div class=\"brand\"><img src=\"data:image/png;base64,\" alt=\"\" aria-hidden=\"true\" style=\"width:31px;height:25px;vertical-align:-6px;margin-right:1px\">ira Panel</div><nav class=\"nav\"><a href=\"/\">Accueil</a><a href=\"/load?nav=wifi\">Réseau</a><a href=\"/load?nav=mqtt\">MQTT</a><a class=\"active\" href=\"/load?nav=params\">Paramètres</a><a href=\"/load?nav=system\">Système</a></nav></div></header>\n"
    "<main>\n"
    "  <div class=\"hero\"><h1>Paramètres</h1><p>Réglages complémentaires de Mira Panel et retours HTTP associés aux widgets.</p></div>\n"
    "  <div class=\"grid\">\n"
    "    <section class=\"card full\">\n"
    "      <h2>Affichage</h2>\n"
    "      <p class=\"hint\">Mira Panel peut gérer seul la luminosité jour/nuit et la veille. Ces mêmes réglages restent pilotables en MQTT pour les automatisations externes.</p>\n"
    "      <form id=\"displayForm\" action=\"/display-save\" method=\"POST\">\n"
    "        <div class=\"display-grid\">\n"
    "          <div class=\"field\"><label for=\"DISPLAY_Jour\">Luminosité jour</label><div class=\"unit-wrap\"><input id=\"DISPLAY_Jour\" name=\"DISPLAY_Jour\" type=\"number\" min=\"1\" max=\"100\" value=\"%DISPLAYDAY%\" required><span class=\"unit\">%%</span></div></div>\n"
    "          <div class=\"field\"><label for=\"DISPLAY_Nuit\">Luminosité nuit</label><div class=\"unit-wrap\"><input id=\"DISPLAY_Nuit\" name=\"DISPLAY_Nuit\" type=\"number\" min=\"1\" max=\"100\" value=\"%DISPLAYNIGHT%\" required><span class=\"unit\">%%</span></div></div>\n"
    "          <div class=\"field\"><label for=\"DISPLAY_DebutNuit\">Début du mode nuit</label><input id=\"DISPLAY_DebutNuit\" name=\"DISPLAY_DebutNuit\" type=\"time\" value=\"%DISPLAYNIGHTSTART%\" required></div>\n"
    "          <div class=\"field\"><label for=\"DISPLAY_FinNuit\">Fin du mode nuit</label><input id=\"DISPLAY_FinNuit\" name=\"DISPLAY_FinNuit\" type=\"time\" value=\"%DISPLAYNIGHTEND%\" required></div>\n"
    "          <div class=\"field\"><label for=\"DISPLAY_Delai\">Mise en veille après</label><div class=\"unit-wrap\"><input id=\"DISPLAY_Delai\" name=\"DISPLAY_Delai\" type=\"number\" min=\"0\" max=\"86400\" value=\"%DISPLAYSLEEPTIMEOUT%\" required><span class=\"unit\">s</span></div><div class=\"footnote\">0 = veille automatique désactivée.</div></div>\n"
    "          <div class=\"field\"><label for=\"DISPLAY_Veille\">Luminosité en veille</label><div class=\"unit-wrap\"><input id=\"DISPLAY_Veille\" name=\"DISPLAY_Veille\" type=\"number\" min=\"0\" max=\"100\" value=\"%DISPLAYSLEEPBRIGHT%\" required><span class=\"unit\">%%</span></div></div>\n"
    "        </div>\n"
    "        <div class=\"switchline\"><div><b>Mode nuit automatique</b><div class=\"hint\" style=\"margin:4px 0 0\">Applique automatiquement les niveaux jour/nuit selon les horaires ci-dessus.</div></div><input id=\"DISPLAY_NuitAuto_Check\" name=\"DISPLAY_NuitAuto_Check\" type=\"checkbox\" value=\"1\" %DISPLAYNIGHTCHECKED%></div>\n"
    "        <div class=\"switchline\"><div><b>Horloge pendant la veille</b><div class=\"hint\" style=\"margin:4px 0 0\">Si désactivé, le rétroéclairage est complètement coupé en veille.</div></div><input id=\"DISPLAY_HorlogeVeille_Check\" name=\"DISPLAY_HorlogeVeille_Check\" type=\"checkbox\" value=\"1\" %DISPLAYCLOCKCHECKED%></div>\n"
    "        <div class=\"actions\"><button class=\"btn\" type=\"submit\">Enregistrer l'affichage</button></div>\n"
    "      </form>\n"
    "      <div class=\"footnote\">MQTT : <span class=\"mono\">mira/&lt;nom&gt;/Display/&lt;clé&gt;/set</span>. Publier <span class=\"mono\">auto</span> sur <span class=\"mono\">brightness/set</span> rend la main à la programmation horaire.</div>\n"
    "    </section>\n"
    "    <section class=\"card full\"><h2>Retours HTTP des widgets</h2><p class=\"hint\">Ces adresses sont utilisées uniquement pour les widgets qui conservent un retour HTTP. Le MQTT se configure dans sa page dédiée.</p>\n"
    "      <form action=\"/save?config=params\" method=\"POST\"><div class=\"params-list\">%PARAMS%</div><div class=\"actions\"><button class=\"btn\" type=\"submit\">Enregistrer</button></div></form>\n"
    "    </section>\n"
    "    <section class=\"card\"><h2>Réseau avancé</h2><p class=\"hint\">Accès aux réglages réseau moins fréquents.</p><div class=\"quick\"><a href=\"/load?nav=listnetwork\">Réseaux enregistrés <span>Modifier ou supprimer</span></a><a href=\"/load?nav=configAP\">Point d'accès Wi-Fi <span>Mode direct / secours</span></a></div></section>\n"
    "    <section class=\"card\"><h2>HTTP</h2><p class=\"hint\">Clé et paramètres utilisés par les requêtes HTTP historiques du panneau.</p><div class=\"quick\"><a href=\"/load?nav=id\">Requêtes HTTP <span>Authentification et clé</span></a></div></section>\n"
    "  </div>\n"
    "</main>\n"
    "<script>\n"
    "function ClickToogle(box,element){document.getElementById(element).value=box.checked?'1':'0';var t=document.getElementById('Value'+element);if(t)t.textContent=box.checked?'Actif':'Inactif';}\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "\n";

static const char mira_beta_mqtt_html[] =
    "\n"
    "<!DOCTYPE html>\n"
    "<html lang=\"fr\">\n"
    "<head>\n"
    "<meta charset=\"UTF-8\">\n"
    "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n"
    "<title>%APP% - MQTT</title>\n"
    "<style>\n"
    ":root{--bg:%LIGHTCOLOR%;--panel:%DARKCOLOR%;--active:%ACTIVECOLOR%;--txt:%TEXTCOLOR%;--ink:#263238;--muted:#607d8b;--line:#d9e2e6;}\n"
    "*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Arial,sans-serif;color:var(--ink)}\n"
    "header{background:var(--panel);color:var(--txt);position:sticky;top:0;z-index:5;box-shadow:0 2px 12px rgba(0,0,0,.12)}\n"
    ".bar{max-width:1040px;margin:auto;min-height:66px;padding:0 18px;display:flex;align-items:center;justify-content:space-between;gap:20px}\n"
    ".brand{font-size:22px;font-weight:800;white-space:nowrap}.nav{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}\n"
    ".nav a{color:var(--txt);text-decoration:none;font-weight:700;padding:10px 12px;border-radius:12px}.nav a:hover,.nav a.active{background:rgba(255,255,255,.14)}\n"
    "main{max-width:940px;margin:28px auto;padding:0 18px 42px}.hero{text-align:left;margin:0 0 16px}.hero h1{font-size:36px;margin:0 0 7px}.hero p{margin:0;color:#455a64}\n"
    ".card{background:#fff;border-radius:20px;padding:24px;margin:16px 0;box-shadow:0 5px 20px rgba(0,0,0,.10)}\n"
    ".card h2{margin:0 0 4px;font-size:23px}.hint{font-size:14px;color:var(--muted);margin:0 0 18px}\n"
    ".grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.full{grid-column:1/-1}\n"
    "label{display:block;font-weight:700;margin:15px 0 7px}input[type=text],input[type=password],input[type=number]{width:100%%;padding:12px 14px;border:1.8px solid #78909c;border-radius:12px;font-size:17px;background:#fff;color:var(--ink)}\n"
    "input:focus{outline:none;border-color:var(--active);box-shadow:0 0 0 3px rgba(0,0,0,.05)}\n"
    ".switchline{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 16px;background:#f5f8f9;border-radius:14px;margin-bottom:6px}.switchline strong{font-size:18px}.switchline input{width:26px;height:26px}\n"
    ".actions{display:flex;justify-content:flex-end;margin-top:22px}.btn,.Bouton{border:0;border-radius:14px;padding:12px 24px;background:var(--active);color:#fff;font-weight:800;font-size:17px;cursor:pointer;text-decoration:none}.btn:active,.Bouton:active{transform:scale(.98)}\n"
    ".topic{padding:13px 15px;background:#f5f8f9;border:1px solid var(--line);border-radius:14px;margin:10px 0}.topic b{display:block;margin-bottom:5px}.topic code{display:block;overflow-wrap:anywhere;font-size:15px;color:#37474f}.note{font-size:14px;color:#546e7a;line-height:1.45;margin-top:14px}\n"
    "table{width:100%%;border-collapse:collapse;margin-top:12px}th,td{padding:11px 10px;border-bottom:1px solid var(--line);text-align:left}th{font-size:13px;text-transform:uppercase;letter-spacing:.04em;color:#546e7a}tr:last-child td{border-bottom:0}\n"
    "@media(max-width:700px){.bar{align-items:flex-start;flex-direction:column;padding-top:14px;padding-bottom:12px}.nav{justify-content:flex-start}.grid{grid-template-columns:1fr}.hero h1{font-size:30px}}\n"
    "</style>\n"
    "</head>\n"
    "<body>\n"
    "<header><div class=\"bar\"><div class=\"brand\"><img src=\"data:image/png;base64,\" alt=\"\" aria-hidden=\"true\" style=\"width:31px;height:25px;vertical-align:-6px;margin-right:1px\">ira Panel</div><nav class=\"nav\"><a href=\"/\">Accueil</a><a href=\"/load?nav=wifi\">Réseau</a><a class=\"active\" href=\"/load?nav=mqtt\">MQTT</a><a href=\"/load?nav=params\">Paramètres</a><a href=\"/load?nav=system\">Système</a></nav></div></header>\n"
    "<main>\n"
    "  <div class=\"hero\"><h1>MQTT</h1><p>Connexion du panneau au broker et configuration des topics Mira.</p></div>\n"
    "  <form action=\"/save?config=params\" method=\"POST\">\n"
    "    <div class=\"card\">\n"
    "      <div class=\"switchline\"><div><strong>Connexion MQTT</strong><div class=\"hint\" style=\"margin:3px 0 0\">Active ou désactive le client MQTT du panneau.</div></div><input id=\"mqttActiveBox\" type=\"checkbox\" %MQTTCHECKED% onchange=\"document.getElementById('MQTT_Actif').value=this.checked?'1':'0'\"></div>\n"
    "      <input id=\"MQTT_Actif\" name=\"MQTT_Actif\" type=\"hidden\" value=\"%MQTTACTIF%\">\n"
    "      <div class=\"grid\">\n"
    "        <div><label>Nom MQTT de l'écran</label><input name=\"MQTT_Nom\" type=\"text\" value=\"%MQTTNOM%\" placeholder=\"panel\"></div>\n"
    "        <div><label>Adresse du broker</label><input name=\"MQTT_Serveur\" type=\"text\" value=\"%MQTTSERVEUR%\" placeholder=\"192.168.1.x\"></div>\n"
    "        <div><label>Port</label><input name=\"MQTT_Port\" type=\"number\" min=\"1\" max=\"65535\" value=\"%MQTTPORT%\"></div>\n"
    "        <div><label>Utilisateur</label><input name=\"MQTT_Utilisateur\" type=\"text\" value=\"%MQTTUSER%\" autocomplete=\"username\"></div>\n"
    "        <div class=\"full\"><label>Mot de passe</label><input name=\"MQTT_Mot_de_passe\" type=\"password\" value=\"%MQTTPASS%\" autocomplete=\"current-password\"></div>\n"
    "      </div>\n"
    "      <div class=\"actions\"><button class=\"btn\" type=\"submit\">Enregistrer</button></div>\n"
    "    </div>\n"
    "  </form>\n"
    "\n"
    "  <div class=\"card\">\n"
    "    <h2>Topics Mira</h2><p class=\"hint\">Le nom de l'écran est intégré automatiquement dans les deux chemins.</p>\n"
    "    <div class=\"topic\"><b>Commandes émises · Actions</b><code>mira/%MQTTNOM%/Actions/&lt;topic&gt;</code></div>\n"
    "    <div class=\"topic\"><b>États reçus · States</b><code>mira/%MQTTNOM%/States/&lt;topic&gt;</code></div>\n"
    "    <p class=\"note\">Une interaction tactile publie dans <b>Actions</b>. Un message reçu dans <b>States</b> met uniquement à jour l'affichage : il ne déclenche jamais une action Jeedom.</p>\n"
    "  </div>\n"
    "\n"
    "  <div class=\"card\"><h2>Widgets déclarés</h2><p class=\"hint\">Liste des noms utilisables comme topics MQTT.</p><table><thead><tr><th>Nom / topic</th><th>Type</th></tr></thead><tbody>%MQTTTABLE%</tbody></table></div>\n"
    "</main>\n"
    "</body>\n"
    "</html>\n"
    "\n";

